from collections import deque

def bfs_shortest_path(graph, start, goal):
    queue = deque([[start]])
    visited = {start}

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == goal:
            return path

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])
    return None

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['E'], 'D': ['GOAL'], 'E': ['GOAL']}
print('Path found:', bfs_shortest_path(graph, 'A', 'GOAL'))
